(()=>{const toggle=document.querySelector('#fullscreen-toggle'),exit=document.createElement('button');exit.id='fullscreen-exit';exit.textContent='退出全螢幕';exit.hidden=true;document.body.append(exit);function sync(){const active=!!document.fullscreenElement||document.body.classList.contains('fullscreen-game');exit.hidden=!active;toggle.textContent=active?'退出全螢幕':'⛶ 全螢幕遊戲'}async function leave(){if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{});document.body.classList.remove('fullscreen-game');sync()}toggle.onclick=async()=>{if(!exit.hidden){await leave();return}document.body.classList.add('fullscreen-game');try{await document.documentElement.requestFullscreen()}catch{}sync()};exit.onclick=leave;document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('fullscreen-game');sync()});document.addEventListener('keydown',e=>{if(e.key==='Escape')leave()});})();
(()=>{const best=document.querySelector('.best-time'),stats=document.querySelector('.stats'),coach=document.querySelector('.v2-coach'),media=window.matchMedia('(min-width:1200px)');function place(){if(media.matches)coach.insertBefore(best,document.querySelector('#fullscreen-toggle'));else stats.append(best)}media.addEventListener('change',place);place()})();

(()=>{document.querySelector('#settings-fullscreen').onclick=()=>{document.querySelector('#mobile-settings-dialog').close();document.querySelector('#fullscreen-toggle').click()}})();
